Which of those differences are real

md`The box plot above is a description. This is a test: a **critical-difference
diagram**, the standard way to compare many methods over many datasets
([Demšar 2006](https://www.jmlr.org/papers/volume7/demsar06a/demsar06a.pdf)). Two methods are drawn connected by a bar when the
evidence does **not** separate them.

Read it in three steps. **The axis is average rank**, best on the left, so
position alone is the ranking. **The bars are the finding**: any two methods
joined by one are statistically indistinguishable over these
${bench_n_datasets} datasets, at the conventional 5% error rate (α = 0.05),
meaning the test tolerates a one-in-twenty chance of calling a difference real
when it is not. And **the width of a bar is the
critical difference**, here ${bench_cd.cd.toFixed(2)} rank positions: two
methods whose average ranks differ by less than that could have swapped places
by chance.`







bench_cd = {
  // Nemenyi post-hoc test over the per-dataset ranks, following Demšar (2006),
  // "Statistical Comparisons of Classifiers over Multiple Data Sets", JMLR 7:
  // https://www.jmlr.org/papers/volume7/demsar06a/demsar06a.pdf
  //
  // CD = q_alpha * sqrt(k(k+1) / 6N), with k methods, N datasets, and q_alpha
  // the Studentized-range critical value divided by sqrt(2). Those come from a
  // table, not a formula; these are Demšar's table 5(a) for alpha = 0.05,
  // indexed by k.
  const Q05 = [NaN, NaN, 1.960, 2.343, 2.569, 2.728, 2.850, 2.949, 3.031,
               3.102, 3.164, 3.219, 3.268, 3.313, 3.354, 3.391, 3.426, 3.458,
               3.489, 3.517, 3.544]
  // The family comes along because the marks colour by it. Leaving it out cost
  // an hour: `fill: "family"` with an undefined value silently drops the datum,
  // so the leads rendered and the dots and labels did not.
  const tools = Array.from(d3.group(bench_ranked, d =&gt; d.display_name),
    ([name, v]) =&gt; ({ name, avg: d3.mean(v, d =&gt; d.rank),
                      family: v[0].family ?? "Unknown" }))
    .sort((a, b) =&gt; d3.ascending(a.avg, b.avg))
  const k = tools.length
  const N = new Set(bench_ranked.map(d =&gt; d.dataset)).size
  const q = Q05[k] ?? Q05[Q05.length - 1]
  const cd = q * Math.sqrt(k * (k + 1) / (6 * N))

  // Friedman test first: the post-hoc comparison is only licensed if the
  // omnibus test rejects "all methods are equivalent". chi2_F is Demšar's
  // equation (3).
  const sum_sq = d3.sum(tools, d =&gt; d.avg ** 2)
  const chi2 = 12 * N / (k * (k + 1)) * (sum_sq - k * (k + 1) ** 2 / 4)
  const df = k - 1

  // Maximal cliques of methods that the test cannot separate. Walking the
  // rank-sorted list, each clique is the longest run starting at i whose span
  // is within CD; a run contained in the previous one adds nothing.
  const cliques = []
  for (let i = 0; i &lt; k; i++) {
    let j = i
    while (j + 1 &lt; k && tools[j + 1].avg - tools[i].avg &lt;= cd) j++
    if (j &gt; i && !(cliques.length && cliques.at(-1)[1] &gt;= j)) cliques.push([i, j])
  }
  return { tools, k, N, q, cd, chi2, df, cliques,
           p: chi2_sf(chi2, df) }
}







// Upper tail of the chi-square distribution, as the regularised incomplete
// gamma Q(df/2, x/2), by series below the crossover and continued fraction
// above it (Numerical Recipes). Needed because the Friedman statistic is the
// licence for the post-hoc test, and quoting a statistic without its p-value
// leaves the reader to look up a table.
chi2_sf = (x, df) =&gt; {
  if (!(x &gt; 0)) return 1
  const a = df / 2, xx = x / 2
  const ln_gamma = z =&gt; {
    // Lanczos approximation; plenty for the two decimal places this is used at.
    const g = [676.5203681218851, -1259.1392167224028, 771.32342877765313,
               -176.61502916214059, 12.507343278686905, -0.13857109526572012,
               9.9843695780195716e-6, 1.5056327351493116e-7]
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - ln_gamma(1 - z)
    z -= 1
    let s = 0.99999999999980993
    for (let i = 0; i &lt; g.length; i++) s += g[i] / (z + i + 1)
    const t = z + g.length - 0.5
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(s)
  }
  const lead = -xx + a * Math.log(xx) - ln_gamma(a)
  if (xx &lt; a + 1) {                       // series for P, then Q = 1 - P
    let sum = 1 / a, term = sum
    for (let n = 1; n &lt; 500; n++) {
      term *= xx / (a + n)
      sum += term
      if (Math.abs(term) &lt; Math.abs(sum) * 1e-15) break
    }
    return 1 - Math.exp(lead + Math.log(sum))
  }
  let b = xx + 1 - a, c = 1e300, d = 1 / b, h = d   // continued fraction for Q
  for (let i = 1; i &lt; 500; i++) {
    const an = -i * (i - a)
    b += 2
    d = an * d + b; if (Math.abs(d) &lt; 1e-300) d = 1e-300
    c = b + an / c;  if (Math.abs(c) &lt; 1e-300) c = 1e-300
    d = 1 / d
    const del = d * c
    h *= del
    if (Math.abs(del - 1) &lt; 1e-15) break
  }
  return Math.exp(lead) * h
}







{
  // Demšar's layout: a rank axis along the top, each method's average rank
