  value: bench_order
})







bench_ap_of_curve = {
  // Trapezoid over the 101 grid points, per tool and level. This is the number
  // the legend quotes, and it is NOT the median of the per-dataset APs: it is
  // the AP of the AVERAGED curve, which is what the benchmark manuscript's
  // figure 1b reports. The two differ by up to 0.12 (InstaNovo: median 0.854,
  // averaged curve 0.736) because averaging curves is not averaging areas.
  const out = new Map()
  for (const [key, pts] of d3.group(bench_curves_t, d =&gt; `${d.level}|${d.tool}`)) {
    const p = pts.slice().sort((a, b) =&gt; d3.ascending(a.coverage, b.coverage))
    let area = 0
    for (let i = 1; i &lt; p.length; i++) {
      area += (p[i].precision + p[i - 1].precision) / 2
              * (p[i].coverage - p[i - 1].coverage)
    }
    out.set(key, area)
  }
  return out
}







