md`The same numbers with no averaging at all: one cell per tool and dataset,
coloured by ${bench_level}-level average precision. Rows run best to worst,
columns easiest to hardest within each group, and the groups themselves
easiest-first. A blank cell is a run that does not exist upstream.`







{
  const rows = bench_t.filter(d =&gt; d[bench_ap_key] != null)
    .map(d =&gt; ({ ...d, ap: d[bench_ap_key] }))
  // Median AP orders everything: rows (tools), columns (datasets) and column
  // groups (categories). Note the columns are NOT faceted by category: Plot
  // shares the x scale across facets, so 17 facets would each carry all 84
  // columns. The grouping is drawn instead, as a header per group plus a rule
  // at its left edge.
  const med_by = keyfn =&gt; {
    const med = d3.rollup(rows, v =&gt; d3.median(v, d =&gt; d.ap), keyfn)
    return Array.from(med).sort((a, b) =&gt; d3.descending(a[1], b[1])).map(d =&gt; d[0])
  }
  // Column and group order come from the tools that ran EVERYWHERE, so a
  // partially evaluated tool cannot move a dataset's difficulty ranking. Row
  // order uses every tool, because a partially evaluated tool still needs a
  // row to sit in.
  const full = rows.filter(d =&gt; d.n_datasets === bench_n_datasets)
  const med_full = keyfn =&gt; {
    const med = d3.rollup(full, v =&gt; d3.median(v, d =&gt; d.ap), keyfn)
    return Array.from(med).sort((a, b) =&gt; d3.descending(a[1], b[1])).map(d =&gt; d[0])
  }
  const cat_order = med_full(d =&gt; d.cat_group)
  const ds_med = d3.rollup(full, v =&gt; d3.median(v, d =&gt; d.ap), d =&gt; d.dataset)
  const ds_cat = new Map(rows.map(d =&gt; [d.dataset, d.cat_group]))
  const datasets = Array.from(ds_med.keys()).sort((a, b) =&gt;
    d3.ascending(cat_order.indexOf(ds_cat.get(a)), cat_order.indexOf(ds_cat.get(b)))
    || d3.descending(ds_med.get(a), ds_med.get(b)))
  // One header per group, anchored on the group's middle column, plus a rule
  // half a band to the left of its first column.
  const groups = cat_order.map(category =&gt; {
    const members = datasets.filter(d =&gt; ds_cat.get(d) === category)
    return { category, n: members.length, first: members[0],
             mid: members[Math.floor(members.length / 2)] }
  })
  const width = 1400, marginLeft = 135, marginRight = 20
  const band = (width - marginLeft - marginRight) / datasets.length
  const tools = med_by(d =&gt; d.display_name)
  // A run that does not exist upstream would otherwise show the page
  // background, and on a white-to-teal scale that is indistinguishable from an
  // average precision of 0. Grey says "not run" and cannot be misread as a
  // score. 60 of the 1512 cells, all of them casanovo-scaling's.
  const present = new Set(rows.map(d =&gt; `${d.display_name}|${d.dataset}`))
  const missing = tools.flatMap(t =&gt; datasets
    .filter(ds =&gt; !present.has(`${t}|${ds}`))
    .map(ds =&gt; ({ display_name: t, dataset: ds })))
  const chart = Plot.plot({
    width,
    height: tools.length * 22 + 320,
    marginLeft, marginRight,
    marginTop: 34,
    marginBottom: 230,   // the rotated dataset names live in here
    x: { domain: datasets, tickRotate: -90, label: null, tickSize: 0 },
    y: { domain: tools, label: null },
    color: { scheme: "BuGn", domain: [0, 1] },
    style: { fontSize: "10px" },
    marks: [
      Plot.cell(missing, {
        x: "dataset", y: "display_name", fill: "#e7eaee", inset: 0.5,
        title: d =&gt; `${d.display_name} was not run on ${d.dataset}`
      }),
      Plot.cell(rows, {
        x: "dataset", y: "display_name", fill: "ap", inset: 0.5,
        tip: { format: { x: false, y: false, fill: false } },
        channels: { "Method": "display_name", "Dataset": "dataset",
                    "Kind": "category", "AP": d =&gt; d.ap.toFixed(3) }
      }),
      Plot.text(groups, {
        x: "mid", text: "category", frameAnchor: "top", dy: -20,
        fontWeight: "bold", fontSize: 11, fill: "#57606a"
      }),
      Plot.ruleX(groups.slice(1), {
        x: "first", dx: -band / 2, stroke: "#8c959f", strokeWidth: 1,
        insetTop: -14
      })
    ],
    tip: plot_tip_style
  })
  // The ramp legend is rendered here rather than by `legend: true` on the
  // scale: Plot sizes that one to the ramp exactly, so the 0.0 and 1.0 tick
  // labels, which are centred on the ends, hang 7 and 8 px outside its frame.
  const legend = Plot.legend({
    color: { scheme: "BuGn", domain: [0, 1],
             label: `${bench_level_label}-level average precision` },
    width: 320, marginLeft: 18, marginRight: 18
  })
  return html`&lt;div class="chart-wrap"&gt;
    &lt;button class="fs-btn" onclick="
      const el = this.parentElement;
      if (document.fullscreenElement) document.exitFullscreen();
      else el.requestFullscreen();
    "&gt;⛶ Fullscreen&lt;/button&gt;
    ${legend}
    &lt;div class="chart-scroll"&gt;${bench_linkify(chart)}&lt;/div&gt;
  &lt;/div&gt;`
}








