pb_placed = {
  // Seven labels, so a greedy pass is enough: take them in metric order and put
  // each above its dot when that box is free, below it otherwise. Obstacles are
  // the labels already placed AND every dot, because two of these submissions
  // sit a pixel apart (ContraNovo and π-PrimeNovo) and a label clear of its own
  // dot can still land on its neighbour's.
  //
  // Boxes are in DATA units, and x and y need their own conversion: the frame
  // is 680 px wide and 552 px tall over the same 1.15-unit domain.
  const R = [-0.05, 1.1], span = R[1] - R[0]
  const px_x = 680 / span, px_y = 552 / span
  // 7.2 px per character at 11 px bold, plus a 3 px pad: the first cut used 6.4
  // and no pad, and ContraNovo against π-PrimeNovo still overlapped by 4 px --
  // an underestimated box is an invisible licence to overlap.
  const LINE_PX = 15, CHAR_PX = 7.2, PAD_PX = 3, DOT_PX = 9
  // Four candidate positions: above or below the dot, on the near row or a
  // second row further out. Two rows are needed, not one: ContraNovo and
  // π-PrimeNovo sit a pixel apart vertically, and AdaNovo's dot blocks the near
  // row above both of them, so with two positions they both ended up below and
  // overlapped each other.
  const SLOTS = [[true, 0, 11], [false, 0, 11], [true, 1, 28], [false, 1, 28]]
  const dots = pb_subs.map(d =&gt; ({
    id: d.id,
    x0: d.x - DOT_PX / px_x, x1: d.x + DOT_PX / px_x,
    y0: d.y - DOT_PX / py(), y1: d.y + DOT_PX / py()
  }))
  function py() { return px_y }
  const hits = (a, b) =&gt; a.x0 &lt; b.x1 && a.x1 &gt; b.x0 && a.y0 &lt; b.y1 && a.y1 &gt; b.y0
  const placed = []
  const out = []
  for (const d of pb_subs) {
    const w = (d.display_name.length * CHAR_PX + 2 * PAD_PX) / px_x
    const h = LINE_PX / px_y
    for (const [i, [above, row, gap_px]] of SLOTS.entries()) {
      const gap = gap_px / px_y
      const y0 = above ? d.y + gap : d.y - gap - h
      const box = { x0: d.x - w / 2, x1: d.x + w / 2, y0, y1: y0 + h }
      const clash = placed.some(o =&gt; hits(box, o))
                 || dots.some(o =&gt; o.id !== d.id && hits(box, o))
      // The last slot is taken whether it clashes or not: a label that is not
      // drawn at all is worse than one that is 4 px from its neighbour, and the
      // chart audit will say if that ever happens.
      if (!clash || i === SLOTS.length - 1) {
        placed.push(box)
        out.push({ ...d, above, row })
        break
      }
    }
  }
  return out
}







md`**Which metric you pick changes the answer**, which is the whole argument in
ProteoBench's own design discussion. ${pb_flip.top_precision} has the highest
peptide-level precision of the ${pb_subs.length} runs, but it answers only
${(pb_flip.coverage * 100).toFixed(0)}% of the spectra; rank the same runs by AUC
and it comes ${pb_flip.rank_by_auc}, behind ${pb_flip.top_auc}. Precision alone
rewards a tool for keeping quiet:

- **Precision** is correct predictions over predictions *made*, at whatever
  coverage the tool chose. A tool that answers only the easy spectra scores well.
- **Precision at full coverage** counts an unanswered spectrum as wrong. It is
  the same number as recall, and it is what the discussion asked for on the
  grounds that some tools skip more than 10% of spectra.
- **AUC** is the area under the precision-coverage curve, swept over every score
  threshold, which is where that discussion landed as the default. It is the
  metric the 84-dataset charts above use as well, so the two benchmarks can be
  read against each other.

*Mass-based* matching accepts a prediction whose residue masses line up within
tolerance, so it cannot tell I from L or deamidated Q/N from E/D; *exact*
requires the sequence. Mass-based is therefore always the higher number, and the
gap is not small: ${pb_gap.median_pct}% of the peptide-level score on median
across these runs.`







pb_flip = {
  const rank = (key) =&gt; pb_t.filter(d =&gt; d.match_type === pb_match && d.level === "peptide")
    .slice().sort((a, b) =&gt; d3.descending(a[key], b[key]))
  const by_prec = rank("precision"), by_auc = rank("auc")
  const top = by_prec[0]
  const pos = by_auc.findIndex(d =&gt; d.id === top.id) + 1
  const ordinal = ["", "first", "second", "third", "fourth", "fifth", "sixth",
                   "seventh", "eighth", "ninth", "tenth"][pos] ?? `${pos}th`
  return { top_precision: top.display_name, coverage: top.coverage,
           rank_by_auc: ordinal, top_auc: by_auc[0].display_name }
}







pb_gap = {
  // How much of the peptide-level score is mass-based matching worth, as a
  // percentage of the mass-based number, on median across submissions.
  const mass = new Map(pb_t.filter(d =&gt; d.level === "peptide" && d.match_type === "mass")
    .map(d =&gt; [d.id, d[pb_metric]]))
  const gaps = pb_t.filter(d =&gt; d.level === "peptide" && d.match_type === "exact")
    .map(d =&gt; (mass.get(d.id) - d[pb_metric]) / mass.get(d.id) * 100)
    .filter(v =&gt; isFinite(v))
  return { median_pct: (d3.median(gaps) ?? 0).toFixed(0) }
}







