The data underneath
Every number on this page was produced by running software over spectra, and the spectra have versions. “Trained on nine-species” names four different objects, and a third of the papers that say it do not say which. These two charts are about that.

dataset_usage_t = transpose(dataset_usage)
dataset_versions_t = transpose(dataset_versions)
dataset_addresses_t = transpose(dataset_addresses)























// One row per (dataset, version-or-null) with its paper count. The null is
// preserved as null all the way from SQL so that "not stated" cannot be
// confused with a version that happens to be called that.
dataset_version_use = {
  const rows = new Map()
  for (const u of dataset_usage_t) {
    const key = `${u.dataset}|${u.version ?? ""}`
    const r = rows.get(key) ?? { dataset: u.dataset, kind: u.kind,
                                 version: u.version ?? null, papers: 0 }
    r.papers += 1
    rows.set(key, r)
  }
  return Array.from(rows.values())
}







// A dataset earns a row only if naming it is actually ambiguous: it has more
// than one version in use, or at least one paper that named no version. A
// single-version deposit cited once is not evidence about anything and there
// are several hundred of them.
version_ambiguity_rows = {
  const by_dataset = d3.group(dataset_version_use, d =&gt; d.dataset)
  const keep = []
  for (const [name, rows] of by_dataset) {
    const total = d3.sum(rows, d =&gt; d.papers)
    const unstated = d3.sum(rows.filter(d =&gt; d.version === null), d =&gt; d.papers)
    const versions = new Set(rows.filter(d =&gt; d.version !== null).map(d =&gt; d.version))
    // Two papers is the floor for "is naming this ambiguous": one paper cannot
    // disagree with anything. The threshold is NOT a slider, because it would
    // be inert -- measured, exactly three datasets in the catalog qualify at
    // any floor from 2 to 4, so a control would imply a longer list than
    // exists.
    if (total &lt; 2) continue
    if (versions.size &lt; 2 && unstated === 0) continue
    for (const r of rows) keep.push({ ...r, total, unstated })
  }
  return keep.sort((a, b) =&gt; b.total - a.total || a.dataset.localeCompare(b.dataset)
                   || (a.version ?? "").localeCompare(b.version ?? ""))
}







version_unstated_share = {
  const total = d3.sum(version_ambiguity_rows, d =&gt; d.papers)
  const unstated = d3.sum(version_ambiguity_rows.filter(d =&gt; d.version === null), d =&gt; d.papers)
  return { total, unstated, pct: total ? Math.round(100 * unstated / total) : 0 }
}







