An amber segment is not sloppiness, usually. A paper that cites the nine per-species PRIDE submissions has told you exactly where its spectra came from. What it has not told you is which curated re-release it ran, and since the revised benchmark removed cross-species peptide redundancy that the original leaked, the two are not interchangeable for measuring generalisation. The catalog records this as a null version rather than guessing.




Where the nine-species benchmark comes from

nine_species_flow = {
  const DATASET = "Nine-species benchmark"
  const versions = dataset_versions_t.filter(d =&gt; d.dataset === DATASET)
  const addrs = dataset_addresses_t.filter(d =&gt; d.dataset === DATASET)
  const provenance = addrs.filter(a =&gt; a.is_provenance)
  const use = dataset_version_use.filter(d =&gt; d.dataset === DATASET)
  const papers_of = new Map(use.map(d =&gt; [d.version ?? "__none__", d.papers]))

  const width = 1100
  const PAD = 10
  const row_px = 34
  const n_rows = Math.max(provenance.length, versions.length + 1)
  const height = Math.max(430, 60 + n_rows * row_px)
  // left 300: 'Candidatus Thiodiazotropha endoloripes . PXD004536' is the
  // longest provenance label and was clipped by 42 px at 232, measured by
  // check_chart_overlap.py. Widening beats truncating a species name.
  const margin = { top: 44, right: 210, bottom: 34, left: 300 }
  const inner_w = width - margin.left - margin.right
  const inner_h = height - margin.top - margin.bottom

  // Three columns: the nine source submissions, the curated deposit, then the
  // versions. Column x positions are fixed; only the version column carries a
  // weight, which is why the two halves are drawn differently (see below).
  const col_x = [0, inner_w * 0.46, inner_w * 0.82]
  const NODE_W = 13

  // LEFT: nine equal boxes. Provenance has no spectra count in the catalog and
  // inventing one would make the ribbons lie, so these are equal height and
  // their ribbons are drawn thin and dashed to say "this is lineage, not flow".
  const left_h = (inner_h - PAD * (provenance.length - 1)) / provenance.length
  const left = provenance.map((a, i) =&gt; ({
    id: a.accession, label: a.part ?? a.accession, url: a.url,
    y0: i * (left_h + PAD), y1: i * (left_h + PAD) + left_h
  }))

  // MIDDLE: the single curated deposit.
  const mid = { id: "MSV000081382", label: "MSV000081382",
                sub: "DeepNovo's curated deposit",
                y0: inner_h * 0.18, y1: inner_h * 0.82 }

  // RIGHT: one box per version plus the unstated bucket, heights proportional
  // to the papers that name them. A version nobody named gets a floor so it is
  // still visible and still labelled -- it exists whether or not it is cited.
  const right_items = versions.map(v =&gt; ({
    id: v.version, label: v.version,
    papers: papers_of.get(v.version) ?? 0,
    n_spectra: v.n_spectra
  }))
  if ((papers_of.get("__none__") ?? 0) &gt; 0) {
    right_items.push({ id: "__none__", label: "version not stated",
                       papers: papers_of.get("__none__"), unstated: true })
  }
  const FLOOR = 16
  const weighted = d3.sum(right_items, d =&gt; d.papers)
  const avail = inner_h - PAD * (right_items.length - 1)
  const floor_total = right_items.filter(d =&gt; d.papers === 0).length * FLOOR
  let cursor = 0
  for (const r of right_items) {
    r.h = r.papers === 0 ? FLOOR
        : ((r.papers / weighted) * (avail - floor_total))
    r.y0 = cursor; r.y1 = cursor + r.h; cursor += r.h + PAD
  }

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, width, height])
    .attr("style", "max-width:100%; height:auto; background:#fbfbfd; font:11px sans-serif;")
  const g = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`)

  const ribbon = (x0, y0a, y0b, x1, y1a, y1b) =&gt; {
    const xm = (x0 + x1) / 2
    return `M${x0},${y0a}C${xm},${y0a} ${xm},${y1a} ${x1},${y1a}`
         + `L${x1},${y1b}C${xm},${y1b} ${xm},${y0b} ${x0},${y0b}Z`
  }

  // provenance ribbons: thin, dashed, uncounted
  for (const l of left) {
    const mid_y = mid.y0 + (mid.y1 - mid.y0) * ((l.y0 + l.y1) / 2) / inner_h
    g.append("path")
      .attr("d", ribbon(col_x[0] + NODE_W, l.y0 + 1, l.y1 - 1,
                        col_x[1], mid_y - 3, mid_y + 3))
      .attr("fill", "#94a3b8").attr("opacity", 0.26)
  }
  // version ribbons: weighted by papers
  let mid_off = 0
  const mid_h = mid.y1 - mid.y0
  for (const r of right_items) {
    const share = weighted ? (r.papers / weighted) : 0
    const h = Math.max(2, share * mid_h)
    g.append("path")
      .attr("d", ribbon(col_x[1] + NODE_W, mid.y0 + mid_off, mid.y0 + mid_off + h,
                        col_x[2], r.y0, r.y1))
      .attr("fill", r.unstated ? "#d97706" : "#0f766e")
      .attr("opacity", r.unstated ? 0.42 : 0.3)
    mid_off += h
  }

  const box = (x, y0, y1, fill) =&gt; g.append("rect")
    .attr("x", x).attr("y", y0).attr("width", NODE_W)
    .attr("height", Math.max(2, y1 - y0)).attr("fill", fill).attr("rx", 2)

  for (const l of left) {
    box(col_x[0], l.y0, l.y1, "#94a3b8")
    g.append("a").attr("href", l.url).attr("target", "_blank")
      .append("text").attr("x", col_x[0] - 8).attr("y", (l.y0 + l.y1) / 2 + 3)
      .attr("text-anchor", "end").attr("fill", "#24292f")
      .text(`${l.label} · ${l.id}`)
  }
  box(col_x[1], mid.y0, mid.y1, "#475569")
  g.append("text").attr("x", col_x[1] + NODE_W / 2).attr("y", mid.y0 - 10)
    .attr("text-anchor", "middle").attr("font-weight", 600).attr("fill", "#24292f")
    .text(mid.label)
  g.append("text").attr("x", col_x[1] + NODE_W / 2).attr("y", mid.y1 + 16)
    .attr("text-anchor", "middle").attr("fill", "#57606a").text(mid.sub)

  for (const r of right_items) {
    box(col_x[2], r.y0, r.y1, r.unstated ? "#d97706" : "#0f766e")
    const t = g.append("text").attr("x", col_x[2] + NODE_W + 8)
      .attr("y", (r.y0 + r.y1) / 2 - (r.n_spectra ? 3 : 0) + 3)
      .attr("fill", "#24292f").attr("font-weight", r.unstated ? 600 : 500)
    t.text(`${r.label} · ${r.papers} paper${r.papers === 1 ? "" : "s"}`)
    if (r.n_spectra)
      g.append("text").attr("x", col_x[2] + NODE_W + 8)
        .attr("y", (r.y0 + r.y1) / 2 + 12).attr("fill", "#57606a")
        .text(`${d3.format(",")(r.n_spectra)} spectra`)
  }

  for (const [x, label] of [[col_x[0], "nine third-party submissions"],
                            [col_x[1], "one curated deposit"],
                            [col_x[2], "five versions in use"]]) {
    g.append("text").attr("x", x).attr("y", -26).attr("fill", "#57606a")
      .attr("font-weight", 600).text(label)
  }
  return svg.node()
}












The left-hand ribbons carry no count, and are drawn pale for that reason. The nine source submissions are unrelated proteomics studies, of honeybees and tomatoes and bottlenose dolphins, whose spectra were re-curated into one deposit; the catalog stores no per-species spectrum count, and sizing those ribbons would have invented one. The right-hand ribbons are weighted by papers. A version with no papers still gets a visible box, because it exists whether or not anyone cited it.





Deposits that travel together
Six of these have no shared provenance at all. They are unrelated studies, of dolphin tissue and bronchoalveolar lavage fluid and diabetic beta-cells, that nobody ever merged into one object. What they share is that the same papers keep reaching for all of them at once, which makes them a benchmark suite in practice and nothing in name. The catalog keeps them as six deposits for that reason, and this chart is where the convention becomes visible.

// Deposits reused by several papers, and the papers reusing them. Derived, not
// a hand-listed set of accessions: a deposit qualifies on its reuse count, so a
// block that forms later appears here without an edit.
couse_min_papers = 4







couse_graph = {
  const by_dataset = d3.group(dataset_usage_t.filter(u =&gt; u.kind === "deposit"),
                              u =&gt; u.dataset)
  const deposits = []
  for (const [name, rows] of by_dataset) {
    const papers = Array.from(new Set(rows.map(r =&gt; r.pub_id))).sort(d3.ascending)
    if (papers.length &gt;= couse_min_papers) deposits.push({ name, papers })
  }
  // A SIGNATURE is the exact set of papers that cite a deposit. Deposits with
  // an identical signature are used by exactly the same work, which is the
  // evidence that they form a suite; the largest such group is highlighted.
  // Grouping on the signature rather than on pairwise overlap keeps the claim
  // falsifiable: these are not "similar", they are identical.
  for (const d of deposits) d.sig = d.papers.join(",")
  const sig_groups = d3.rollups(deposits, v =&gt; v.length, d =&gt; d.sig)
    .sort((a, b) =&gt; b[1] - a[1])
  const block_sig = sig_groups.length && sig_groups[0][1] &gt; 1 ? sig_groups[0][0] : null
  // A deposit one paper short of the block is still part of the practice, so
  // near-members are marked too: the same signature plus any one extra paper.
  const block_papers = block_sig ? new Set(block_sig.split(",")) : new Set()
  for (const d of deposits) {
    d.in_block = d.sig === block_sig
    d.near_block = !d.in_block && block_sig
      && block_papers.size &gt; 0
      && [...block_papers].every(p =&gt; d.papers.map(String).includes(p))
  }
  const acc_of = new Map()
  for (const a of dataset_addresses_t) if (!acc_of.has(a.dataset)) acc_of.set(a.dataset, a.accession)
  const title_of = new Map(pubs_t.map(p =&gt; [p.id, p]))
  const paper_deg = new Map()
  for (const d of deposits) for (const p of d.papers) paper_deg.set(p, (paper_deg.get(p) ?? 0) + 1)
  const papers = Array.from(paper_deg.entries())
    .map(([id, deg]) =&gt; {
      const p = title_of.get(id)
      const first_model = (p?.models_described ?? "").split(",")[0].trim()
      const raw = first_model || (p?.title ?? `publication ${id}`)
      return { id, deg, title: p?.title ?? "", year: p?.year,
               // 40 characters keeps the longest label inside the right margin
               // at 11 px; measured, three ran past the frame at no limit.
               label: raw.length &gt; 40 ? raw.slice(0, 39) + "\u2026" : raw }
    })
    .sort((a, b) =&gt; b.deg - a.deg || d3.ascending(a.label, b.label))
  // Two papers can share a leading method name -- a paper describing both
  // PandaNovo and pi-HelixNovo leads with the same string as the pi-HelixNovo
  // paper -- and two identical labels in one column are unreadable. Add the
  // year only where it is needed to tell them apart.
  {
    const seen = d3.rollup(papers, v =&gt; v.length, d =&gt; d.label)
    for (const p of papers) {
      if (seen.get(p.label) &gt; 1 && p.year) p.label = `${p.label} (${p.year})`
    }
  }
  deposits.sort((a, b) =&gt;
       (b.in_block | 0) - (a.in_block | 0)
    || (b.near_block | 0) - (a.near_block | 0)
    || b.papers.length - a.papers.length
    || d3.ascending(a.name, b.name))
  return { deposits, papers, acc_of, block_size: deposits.filter(d =&gt; d.in_block).length }
}







html`&lt;p style="margin:0.4rem 0 0.9rem; color:#57606a;"&gt;
&lt;b&gt;${couse_graph.deposits.length}&lt;/b&gt; deposits are reused by
${couse_min_papers} or more papers. &lt;b&gt;${couse_graph.block_size}&lt;/b&gt; of them are
cited by the &lt;i&gt;identical&lt;/i&gt; set of
&lt;b&gt;${couse_graph.deposits.find(d =&gt; d.in_block)?.papers.length ?? 0}&lt;/b&gt; papers,
drawn in teal below, with near-members in a lighter shade: not merely similar
usage, the same set exactly.&lt;/p&gt;`







couse_flow = {
  const { deposits, papers, acc_of } = couse_graph
  const width = 1100
  const PAD = 7
  const NODE_W = 13
  const height = Math.max(520, 56 + papers.length * 25)
  // right 330: the longest paper label, truncated to 40 characters plus its
  // degree suffix, ran 3 labels past the frame at 250.
  const margin = { top: 42, right: 330, bottom: 26, left: 300 }
  const inner_w = width - margin.left - margin.right
  const inner_h = height - margin.top - margin.bottom

  // Both columns are weighted by edge count, and every edge weighs 1: a paper
  // either used a deposit or did not, and there is no spectrum count here to
  // scale by. So node height is degree, which is the honest encoding.
  const total_edges = d3.sum(deposits, d =&gt; d.papers.length)
  const lay = (nodes, degree) =&gt; {
    const avail = inner_h - PAD * (nodes.length - 1)
    let y = 0
    for (const n of nodes) {
      n.h = (degree(n) / total_edges) * avail
      n.y0 = y; n.y1 = y + n.h; y += n.h + PAD
    }
  }
  lay(deposits, d =&gt; d.papers.length)
  lay(papers, p =&gt; p.deg)

  const COL = { block: "#0f766e", near: "#5eada6", other: "#94a3b8" }
  const colour = d =&gt; d.in_block ? COL.block : d.near_block ? COL.near : COL.other
  const paper_by_id = new Map(papers.map(p =&gt; [p.id, p]))
  const l_off = new Map(), r_off = new Map()

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, width, height])
    .attr("style", "max-width:100%; height:auto; background:#fbfbfd; font:11px sans-serif;")
  const g = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`)
  const ribbon = (x0, y0a, y0b, x1, y1a, y1b) =&gt; {
    const xm = (x0 + x1) / 2
    return `M${x0},${y0a}C${xm},${y0a} ${xm},${y1a} ${x1},${y1a}`
         + `L${x1},${y1b}C${xm},${y1b} ${xm},${y0b} ${x0},${y0b}Z`
  }
  for (const d of deposits) {
    for (const pid of d.papers) {
      const p = paper_by_id.get(pid)
      if (!p) continue
      const lh = d.h / d.papers.length
      const rh = p.h / p.deg
      const lo = l_off.get(d.name) ?? 0
      const ro = r_off.get(p.id) ?? 0
      g.append("path")
        .attr("d", ribbon(NODE_W, d.y0 + lo, d.y0 + lo + lh,
                          inner_w, p.y0 + ro, p.y0 + ro + rh))
        .attr("fill", colour(d))
        .attr("opacity", d.in_block ? 0.34 : 0.17)
      l_off.set(d.name, lo + lh)
      r_off.set(p.id, ro + rh)
    }
  }
  for (const d of deposits) {
    g.append("rect").attr("x", 0).attr("y", d.y0).attr("width", NODE_W)
      .attr("height", Math.max(2, d.h)).attr("fill", colour(d)).attr("rx", 2)
    const acc = acc_of.get(d.name) ?? ""
    const t = g.append("text").attr("x", -8).attr("y", (d.y0 + d.y1) / 2 - 2)
      .attr("text-anchor", "end").attr("fill", "#24292f")
      .attr("font-weight", d.in_block ? 600 : 400)
    t.text(acc)
    g.append("text").attr("x", -8).attr("y", (d.y0 + d.y1) / 2 + 11)
      .attr("text-anchor", "end").attr("fill", "#57606a")
      // 44 characters keeps the longest repository title inside the 300 px
      // left margin at 11 px; the full name is on the paper pages.
      .text(d.name.length &gt; 44 ? d.name.slice(0, 43) + "…" : d.name)
  }
  for (const p of papers) {
    g.append("rect").attr("x", inner_w).attr("y", p.y0).attr("width", NODE_W)
      .attr("height", Math.max(2, p.h)).attr("fill", "#475569").attr("rx", 2)
    g.append("text").attr("x", inner_w + NODE_W + 8).attr("y", (p.y0 + p.y1) / 2 + 3)
      .attr("fill", "#24292f").attr("font-weight", p.deg &gt;= 5 ? 600 : 400)
      .text(`${p.label}${p.deg &gt; 1 ? ` · ${p.deg}` : ""}`)
  }
  for (const [x, anchor, label] of [[0, "start", "deposit"],
                                    [inner_w + NODE_W, "end", "papers reusing it"]]) {
    g.append("text").attr("x", x).attr("y", -24).attr("text-anchor", anchor)
      .attr("fill", "#57606a").attr("font-weight", 600).text(label)
  }
  return svg.node()
}












Every ribbon here weighs the same, deliberately. A paper either used a deposit or it did not, and unlike the nine-species flow above there is no spectrum count to scale by, so node height is simply degree. The teal block is computed from an identical citing-paper signature rather than from pairwise similarity, which is what makes it a claim worth printing: these deposits are not used by overlapping sets of papers, they are used by the same set. The lighter shade is a deposit matching that signature plus one extra paper.





The dataset network

md`A dataset is in this graph once **two or more** papers link to it: a deposit
cited only by the study that made it says nothing about reuse, and there are
${dataset_versions_t.length - 0 &gt; 0 ? (all_dataset_rows.filter(d =&gt; d.papers &lt; 2).length) : 0}
of those. Diamonds are datasets, sized by how many papers use them and coloured
by kind; circles are papers, sized by how many of these datasets they draw on.`







dataset_paper_network = {
  // 1250, not the 1400 the other two force charts use. This graph has 176 nodes
  // against their 173 and 360, but its links are dense enough that it settles
  // into a tighter ball: at 1400 the nodes filled 69% of the frame width with
  // nothing within 179 px of the right edge. Narrowing the frame to the content
  // beats pushing the content at the frame, which is how nodes end up parked on
  // the border.
  const width = 1250
  // 800, between the co-authorship chart's 650 for 173 nodes and the
  // bipartite's 1000 for 360. This holds 176, and the density that pinned
  // nodes to the frame in those two scales with node count, not with ambition.
  const PLOT_H = 800
  const TITLE_PX = 34
  const LEGEND_H = 56

  // Edges are unweighted on purpose: a paper either used a dataset or it did
  // not, and there is no spectrum count to scale by. "Weighted by reuse" is
  // therefore carried by NODE SIZE (degree), not by edge width.
  const papers_of = d3.group(dataset_usage_t, u =&gt; u.dataset)
  const ds_nodes = []
  for (const [name, rows] of papers_of) {
    const pubs = Array.from(new Set(rows.map(r =&gt; r.pub_id)))
    if (pubs.length &lt; 2) continue
    ds_nodes.push({ id: `ds:${name}`, type: "dataset", name,
                    kind: rows[0].kind, pubs, degree: pubs.length })
  }
  const kept = new Set(ds_nodes.flatMap(d =&gt; d.pubs))
  const pub_by_id = new Map(pubs_t.map(p =&gt; [p.id, p]))
  const paper_nodes = Array.from(kept).map(id =&gt; {
    const p = pub_by_id.get(id)
    const model = (p?.models_described ?? "").split(",")[0].trim()
    const raw = model || (p?.title ?? `publication ${id}`)
    return { id: `p:${id}`, type: "paper", pub_id: id,
             name: raw.length &gt; 32 ? raw.slice(0, 31) + "…" : raw,
             full: p?.title ?? "", degree: 0 }
  })
  const paper_by_key = new Map(paper_nodes.map(n =&gt; [n.id, n]))
  const links = []
  for (const d of ds_nodes) for (const pid of d.pubs) {
    const t = paper_by_key.get(`p:${pid}`)
    if (!t) continue
    links.push({ source: d.id, target: t.id })
    t.degree += 1
  }
  const nodes = [...ds_nodes, ...paper_nodes]
  const max_deg = d3.max(nodes, d =&gt; d.degree) ?? 1
  const NODE_R = d =&gt; d.type === "dataset"
    ? 5 + 11 * Math.sqrt(d.degree / max_deg)
    : 3.5 + 7 * Math.sqrt(d.degree / max_deg)

  const KIND_COLOUR = { benchmark: "#0f766e", training: "#b45309", deposit: "#64748b" }
  const colour = d =&gt; d.type === "paper" ? "#cbd5e1" : (KIND_COLOUR[d.kind] ?? "#94a3b8")

  // Cluster targets on a phyllotaxis disc, by kind for a dataset and by its
  // most-used dataset's kind for a paper, so every node has a target. A RING of
  // targets is what emptied the middle of the two older force charts; this is
  // area-uniform instead. Strength is low (0.06) because the point is to
  // separate the three populations loosely, not to draw three blobs.
  const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5))
  const kinds = Array.from(new Set(ds_nodes.map(d =&gt; d.kind))).sort()
  // Recentred on their own centroid. A phyllotaxis walk of only three points
  // is not symmetric about the origin, so the three targets drifted the whole
  // network off-centre: measured, nodes spanned 36-902 px of a 1099 px frame,
  // leaving 197 px empty on the right against 36 on the left. Subtracting the
  // centroid costs nothing and keeps the disc's area-uniform spacing.
  const raw_centers = kinds.map((k, i) =&gt; {
    const r = Math.sqrt((i + 0.5) / kinds.length)
    const a = i * GOLDEN_ANGLE
    return [Math.cos(a) * r * width * 0.34, Math.sin(a) * r * PLOT_H * 0.26]
  })
  // kind_of FIRST: the weighted centroid below reads it, and `const` is not
  // hoisted, so computing the centroid above this threw a ReferenceError.
  const kind_of = new Map()
  for (const d of ds_nodes) kind_of.set(d.id, d.kind)
  for (const p of paper_nodes) {
    const ks = ds_nodes.filter(d =&gt; d.pubs.includes(p.pub_id)).map(d =&gt; d.kind)
    kind_of.set(p.id, d3.mode(ks) ?? kinds[0])
  }
  // WEIGHTED by group size, not a plain mean. The unweighted centroid moved the
  // targets but not the network: 72 of the 83 datasets are deposits, so the
  // layout's centre of mass sits at THAT group's target wherever the three
  // targets happen to be, and the right-hand gap stayed at 191 px of 1099.
  // Weighting puts the heaviest group near the middle, which is what centring
  // a lopsided graph actually means.
  const kind_weight = new Map(kinds.map(k =&gt;
    [k, nodes.filter(n =&gt; kind_of.get(n.id) === k).length || 1]))
  const w_total = d3.sum(kinds, k =&gt; kind_weight.get(k))
  const cx0 = d3.sum(kinds, (k, i) =&gt; raw_centers[i][0] * kind_weight.get(k)) / w_total
  const cy0 = d3.sum(kinds, (k, i) =&gt; raw_centers[i][1] * kind_weight.get(k)) / w_total
  const centers = new Map()
  kinds.forEach((k, i) =&gt; {
    centers.set(k, [width / 2 + raw_centers[i][0] - cx0,
                    (TITLE_PX + PLOT_H) / 2 + raw_centers[i][1] - cy0])
  })
  const target = d =&gt; centers.get(kind_of.get(d.id)) ?? [width / 2, PLOT_H / 2]

  const sim = d3.forceSimulation(nodes)
    // distance 78 and charge -240, not 58 and -170. At the tighter settings the
    // layout CONVERGED but did not fill: 176 nodes occupied 663 px of a 1099 px
    // frame, because the deposit cluster holds about 150 of them and a charge
    // capped at 190 px cannot separate a ball that dense. Measured node spread
    // is the number to tune against here, exactly as wall_probe.js was for the
    // other two -- the label audit passes happily on a compact knot.
    .force("link", d3.forceLink(links).id(d =&gt; d.id).distance(78).strength(0.2))
    // Still capped, for the reason recorded on the two charts below: an
    // unbounded forceManyBody grows its outward pressure with the square of the
    // node count and the layout never converges inside the frame.
    .force("charge", d3.forceManyBody().strength(-240).distanceMax(210))
    .force("collide", d3.forceCollide().radius(d =&gt; NODE_R(d) + 3))
    .force("center", d3.forceCenter(width / 2, (TITLE_PX + PLOT_H) / 2))
    .force("kx", d3.forceX(d =&gt; target(d)[0]).strength(0.06))
    .force("ky", d3.forceY(d =&gt; target(d)[1]).strength(0.06))

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, width, PLOT_H + LEGEND_H])
    .attr("style", "max-width:100%; height:auto; font:11px sans-serif; cursor:grab;")
  svg.append("text").attr("x", width / 2).attr("y", 22).attr("text-anchor", "middle")
    .attr("font-size", 16).attr("font-weight", "bold").attr("fill", "#24292f")
    .text(`Datasets and the papers reusing them · ${ds_nodes.length} datasets, `
          + `${paper_nodes.length} papers, ${links.length} links`)

  const g = svg.append("g")
  svg.call(d3.zoom().on("zoom", ev =&gt; g.attr("transform", ev.transform)))
  const link = g.append("g").attr("stroke", "#94a3b8").attr("stroke-opacity", 0.3)
    .selectAll("line").data(links).join("line").attr("stroke-width", 1)

  const node_g = g.append("g").selectAll("g").data(nodes).join("g")
    .call(d3.drag()
      .on("start", (ev, d) =&gt; { if (!ev.active) sim.alphaTarget(0.25).restart(); d.fx = d.x; d.fy = d.y })
      .on("drag",  (ev, d) =&gt; { d.fx = ev.x; d.fy = ev.y })
      .on("end",   (ev, d) =&gt; { if (!ev.active) sim.alphaTarget(0); d.fx = null; d.fy = null }))
  node_g.filter(d =&gt; d.type === "dataset").append("rect")
    .attr("width", d =&gt; NODE_R(d) * 1.7).attr("height", d =&gt; NODE_R(d) * 1.7)
    .attr("x", d =&gt; -NODE_R(d) * 0.85).attr("y", d =&gt; -NODE_R(d) * 0.85)
    .attr("transform", "rotate(45)")
    .attr("fill", colour).attr("stroke", "white").attr("stroke-width", 1)
  node_g.filter(d =&gt; d.type === "paper").append("circle")
    .attr("r", NODE_R).attr("fill", colour).attr("stroke", "white").attr("stroke-width", 1)
  node_g.append("title").text(d =&gt; d.type === "dataset"
    ? `${d.name}\n${d.kind} · ${d.degree} papers`
    : `${d.full || d.name}\n${d.degree} of these datasets`)

  const label = g.append("g").selectAll("text").data(nodes).join("text")
    .attr("font-size", 10)
    .attr("font-weight", d =&gt; d.type === "dataset" ? 600 : 400)
    .attr("fill", d =&gt; d.type === "dataset" ? "#24292f" : "#475569")
    .attr("paint-order", "stroke").attr("stroke", "white").attr("stroke-width", 2.5)
    .text(d =&gt; d.name)

  // Same greedy pass as the other two force charts: six positions per name in
  // descending degree, hidden if none is free. Every node still answers a
  // hover, so the hidden ones are the least connected rather than lost.
  const LABEL_CHAR_PX = 5.8
  const SIDES = [[1, 0], [-1, 0], [1, -11], [-1, -11], [1, 11], [-1, 11]]
  const label_order = nodes.slice().sort((a, b) =&gt; d3.descending(a.degree, b.degree))
  const place_labels = () =&gt; {
    const shown = []
    for (const d of label_order) {
      const w = d.name.length * LABEL_CHAR_PX
      d.label_on = false
      for (const [side, dy] of SIDES) {
        const x0 = side &gt; 0 ? d.x + NODE_R(d) + 3 : d.x - NODE_R(d) - 3 - w
        const y = d.y + dy
        const box = { x0, x1: x0 + w, y0: y - 6, y1: y + 6 }
        if (box.x0 &lt; 0 || box.x1 &gt; width || box.y0 &lt; TITLE_PX || box.y1 &gt; PLOT_H) continue
        const clash =
          shown.some(o =&gt; box.x0 &lt; o.x1 + 2 && box.x1 + 2 &gt; o.x0 && box.y0 &lt; o.y1 && box.y1 &gt; o.y0) ||
          nodes.some(n =&gt; box.x0 &lt; n.x + NODE_R(n) && box.x1 &gt; n.x - NODE_R(n)
                       && box.y0 &lt; n.y + NODE_R(n) && box.y1 &gt; n.y - NODE_R(n))
        if (!clash) { d.label_on = true; d.label_side = side; d.label_dy = dy; shown.push(box); break }
      }
    }
  }
  let tick_n = 0
  sim.on("tick", () =&gt; {
    for (const d of nodes) {
      const r = NODE_R(d) + 2
      d.x = Math.max(r, Math.min(width - r, d.x))
      d.y = Math.max(TITLE_PX + r, Math.min(PLOT_H - r, d.y))
    }
    link.attr("x1", d =&gt; d.source.x).attr("y1", d =&gt; d.source.y)
        .attr("x2", d =&gt; d.target.x).attr("y2", d =&gt; d.target.y)
    node_g.attr("transform", d =&gt; `translate(${d.x},${d.y})`)
    if ((tick_n++ & 3) === 0) place_labels()
    label.attr("x", d =&gt; d.x).attr("y", d =&gt; d.y + (d.label_dy ?? 0))
      .attr("display", d =&gt; d.label_on ? null : "none")
      .attr("dx", d =&gt; (d.label_side ?? 1) &gt; 0 ? NODE_R(d) + 3 : -(NODE_R(d) + 3))
      .attr("text-anchor", d =&gt; (d.label_side ?? 1) &gt; 0 ? "start" : "end")
  })

  const lg = svg.append("g").attr("transform", `translate(40,${PLOT_H + 20})`)
  let lx = 0
  for (const k of kinds) {
    lg.append("rect").attr("x", lx).attr("y", -6).attr("width", 11).attr("height", 11)
      .attr("transform", `rotate(45,${lx + 5.5},-0.5)`).attr("fill", KIND_COLOUR[k] ?? "#94a3b8")
    lg.append("text").attr("x", lx + 16).attr("y", 3).attr("fill", "#24292f").text(k)
    lx += 20 + k.length * 7
  }
  lg.append("circle").attr("cx", lx + 6).attr("cy", -1).attr("r", 5).attr("fill", "#cbd5e1")
  lg.append("text").attr("x", lx + 16).attr("y", 3).attr("fill", "#24292f").text("paper")
  return svg.node()
}








