all_dataset_rows = {
  const papers_of = d3.group(dataset_usage_t, u =&gt; u.dataset)
  const versions_of = d3.group(dataset_versions_t, v =&gt; v.dataset)
  const addrs_of = d3.group(dataset_addresses_t, a =&gt; a.dataset)
  const rows = []
  for (const v of versions_of.keys()) {
    const vs = versions_of.get(v) ?? []
    const us = papers_of.get(v) ?? []
    const ad = addrs_of.get(v) ?? []
    rows.push({
      Dataset: v,
      Kind: vs[0]?.kind ?? "",
      Versions: vs.length,
      papers: new Set(us.map(u =&gt; u.pub_id)).size,
      Deposited: us.filter(u =&gt; u.role === "introduces").length &gt; 0 ? "yes" : "",
      Spectra: d3.max(vs, x =&gt; x.n_spectra) ?? null,
      // Every accession, so the search box reaches the long tail: typing
      // PXD004424 or "zenodo" finds its dataset, which is the whole reason
      // this table exists alongside the charts.
      Accessions: ad.map(a =&gt; a.accession).join(" "),
      Repositories: Array.from(new Set(ad.map(a =&gt; a.repository))).sort().join(", "),
      url: ad.find(a =&gt; a.url)?.url ?? null
    })
  }
  return rows.sort((a, b) =&gt; b.papers - a.papers || d3.ascending(a.Dataset, b.Dataset))
}







