viewof selected_pubs = {
  // Decorate each row with the venue's OpenAlex 2-year citedness (or null).
  // Also rewrite the comma-separated `models` string to append known aliases
  // (e.g. π-HelixNovo → "π-HelixNovo (aka PandaNovo)") so renamed methods stay
  // searchable by their historical name in the table's filter box.
  const aliases_by_model = new Map(
    algorithms_t.filter(a =&gt; a.aliases).map(a =&gt; [a.model, a.aliases])
  )
  const annotate_models = s =&gt; (s ?? "")
    .split(",").map(x =&gt; x.trim()).filter(Boolean)
    .map(m =&gt; aliases_by_model.has(m) ? `${m} (aka ${aliases_by_model.get(m)})` : m)
    .join(", ")
  const search_with_if = search.map(r =&gt; ({
    ...r,
    models: annotate_models(r.models),
    // The full date as an ISO STRING, not the Date object and not the year. It
    // is what the table sorts on, and a string keeps three things working at
    // once: ISO dates sort lexicographically, the search box can match
    // "2026-09", and the cell needs no formatter.
    date_str: fmt_day(r.date),
    citedness: journal_impact_by_name.get(r.journal)?.two_yr_citedness ?? null
  }))
  const table = Inputs.table(search_with_if, {
    // `id` is the insertion order, so sorting on it descending answers "what
    // was added last", which the Date column cannot: an older paper added today
    // sorts by its own date, wherever that falls.
    columns: ["id", "date_str", "models", "version", "kind", "is_dl", "acquisition", "title", "authors", "journal", "citedness", "type", "repo"],
    header: {
      id: "#",
      date_str: "Date", models: "Method(s)", version: "Ver.", kind: "Kind", is_dl: "DL?", acquisition: "Acq.",
      title: "Title", authors: "Authors", journal: "Venue", citedness: "IF₂ᵧᵣ", type: "Type", repo: "Code"
    },
    format: {
      is_dl: v =&gt; v === 1 || v === true ? "DL" : (v === 0 || v === false ? "classical" : ""),
      citedness: c =&gt; c == null ? "" : c.toFixed(1),
      // The title now goes to this catalog's own page for the paper, with the
      // publisher/DOI kept as a separate chip so both destinations stay
      // reachable. The row index lookup is load-bearing: 19 titles are shared
      // by a preprint and its journal version, so the title string alone cannot
      // identify the row.
      title: (t, i) =&gt; {
        const row = search_with_if[i]
        const internal = page_href("publications", row?.id)
        const external = row?.url || (row?.doi ? `https://doi.org/${row.doi}` : null)
        const label = internal ? htl.html`&lt;a href=${internal}&gt;${t}&lt;/a&gt;` : t
        return external
          ? htl.html`${label} &lt;a href="${external}" target="_blank" rel="noopener"
              title="Publisher / DOI" style="text-decoration:none"&gt;↗&lt;/a&gt;`
          : label
      },
      // annotate_models() appended "(aka ...)" to renamed tools. Keep that
      // visible but link only the name part, which is the slug key.
      models: m =&gt; {
        const parts = String(m ?? "").split(",").map(x =&gt; x.trim()).filter(Boolean)
        const out = []
        parts.slice(0, 4).forEach((part, idx) =&gt; {
          if (idx) out.push(", ")
          const alias = part.match(/^(.*?)(\s*\(aka [^)]*\))$/)
          const name = alias ? alias[1] : part
          out.push(page_link("algorithms", name, name))
          if (alias) out.push(alias[2])
        })
        if (parts.length &gt; 4) out.push(` +${parts.length - 4}`)
        return htl.html`${out}`
      },
      // Three names then a count: a 53-author consortium paper would otherwise
      // fill the row with links.
      authors: a =&gt; page_links("authors", a, { max: 3 }),
      journal: j =&gt; page_link("venues", j, j),
      repo: r =&gt; {
        if (!r) return ""
        // The repository column holds either a single URL or two whitespace-separated URLs
        // (a few RNovA-style entries). Render up to three short link chips.
        const urls = String(r).split(/\s+/).filter(s =&gt; /^https?:\/\//.test(s)).slice(0, 3)
        if (!urls.length) return ""
        return htl.html`${urls.map(u =&gt; htl.html`&lt;a href="${u}" target="_blank" rel="noopener" title="${u}" style="margin-right:4px"&gt;↗&lt;/a&gt;`)}`
      }
    },
    // On the DATE, not the year. Sorting on a year descending leaves the rows
    // within each year in the array's own order, which is the SQL's
    // `ORDER BY p.publication_date` -- oldest first. So the table opened on
    // January 2026, and a paper added today landed sixty rows below it in a
    // column that said 2026 all the way down.
    sort: "date_str",
    reverse: true,
    rows: 25,
    width: { id: 50, date_str: 96, type: 100, models: 130, version: 60, kind: 130, is_dl: 70, acquisition: 70, citedness: 70, repo: 60 }
  })
  // Reflect the inner Inputs.table's value/input on the fullscreen wrapper so
  // `viewof selected_pubs` exposes the rows the user has ticked, used by the
  // BibTeX download button below.
  const wrapper = html`&lt;div class="chart-wrap"&gt;
    &lt;button class="fs-btn" onclick="
      const el = this.parentElement;
      if (document.fullscreenElement) document.exitFullscreen();
      else el.requestFullscreen();
    "&gt;⛶ Fullscreen&lt;/button&gt;
    &lt;div class="chart-scroll"&gt;${table}&lt;/div&gt;
  &lt;/div&gt;`
  Object.defineProperty(wrapper, "value", { get: () =&gt; table.value })
  table.addEventListener("input", e =&gt; wrapper.dispatchEvent(new CustomEvent("input", { bubbles: false })))
  return wrapper
}







